// Generated by `just generate` from `src/plugins/dotclaude/slices/spec/adapters/ready.ts`. Edit the source and run `just generate`.
// `dotclaude-spec ready [<id>] [--json]`: the packages that can start now.
// A package is ready when its state is `planned`, each dep is `done`,
// and its `owns` do not overlap the `owns` of a package in `doing`, `verified`, or `approved`.
// The printed set has no overlap: a package is skipped when its `owns` overlap a package printed before it.

import { ownsOverlap } from "../domain/deps.ts";
import { parseArgs } from "./args.ts";
import { loadChange } from "./graph.ts";
import { type Run, resolveId } from "./run.ts";

/** The states of a package whose `owns` are taken. */
const TAKING = ["doing", "verified", "approved"];

/** Prints the id of each ready package of the change, one for each line, in the order of wave and id. */
export const readyCommand = async (
  run: Run,
  args: string[],
): Promise<number> => {
  const parsed = parseArgs(args);
  if (typeof parsed === "string" || parsed.words.length > 1) {
    run.io.error(
      typeof parsed === "string"
        ? parsed
        : "Usage: dotclaude-spec ready [<id>] [--json]",
    );
    return 2;
  }
  const id = await resolveId(run, parsed.words[0]);
  if (id === null) return 1;
  const loaded = await loadChange(run, id);
  if (loaded === null) return 1;
  const { states, packages } = loaded;
  const taken = packages
    .filter((p) => TAKING.includes(states[p.id] ?? ""))
    .map((p) => p.owns);
  const ready = packages
    .filter((p) => states[p.id] === "planned")
    .filter((p) => p.deps.every((d) => states[d] === "done"))
    .filter((p) => {
      if (taken.some((owns) => ownsOverlap(p.owns, owns))) return false;
      taken.push(p.owns);
      return true;
    })
    .map((p) => p.id);
  if (parsed.json) {
    run.io.log(JSON.stringify(ready));
    return 0;
  }
  if (ready.length === 0) {
    run.io.log(`No package of \`${id}\` is ready.`);
    return 0;
  }
  for (const pkg of ready) run.io.log(pkg);
  return 0;
};
